CREATE TABLE IF NOT EXISTS public.recurring_expenses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE, vehicle_id uuid REFERENCES public.vehicles(id) ON DELETE SET NULL, device_id uuid REFERENCES public.gps_devices(id) ON DELETE SET NULL, created_by uuid NOT NULL REFERENCES auth.users(id) ON DELETE RESTRICT, amount numeric(14,2) NOT NULL CHECK (amount >= 0), tax_amount numeric(14,2) NOT NULL DEFAULT 0 CHECK (tax_amount >= 0), category text NOT NULL, description text, vendor text, payment_method text, frequency text NOT NULL CHECK (frequency IN ('WEEKLY','MONTHLY','QUARTERLY','YEARLY')), next_due_date date NOT NULL, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());